import{_ as o,o as n,c as r,a6 as t}from"./chunks/framework.QBF2cGGQ.js";const m=JSON.parse('{"title":"04 · Agent 智能体","description":"","frontmatter":{},"headers":[],"relativePath":"guide/04-agent.md","filePath":"guide/04-agent.md","lastUpdated":1793330392000}'),i={name:"guide/04-agent.md"};function a(p,s,l,g,e,u){return n(),r("div",null,[...s[0]||(s[0]=[t('<h1 id="_04-·-agent-智能体" tabindex="-1">04 · Agent 智能体 <a class="header-anchor" href="#_04-·-agent-智能体" aria-label="Permalink to &quot;04 · Agent 智能体&quot;">​</a></h1><blockquote><p><strong>投入权重：15%</strong> · 最热也最容易翻车的一块。 核心矛盾只有一个：<strong>单步准确率乘以步数会衰减</strong>，所以工程重点全在&quot;如何减少步数&quot;和&quot;如何兜住错误&quot;。</p></blockquote><h2 id="先把预期调对" tabindex="-1">先把预期调对 <a class="header-anchor" href="#先把预期调对" aria-label="Permalink to &quot;先把预期调对&quot;">​</a></h2><p>绝大多数失败的 Agent 项目，问题不在模型不够强，而在设计者默认&quot;模型会自己搞定&quot;。真实情况是：模型在单步上表现不错，但每一步都有几个百分点的失败率，十步之后就只剩六成。这不是模型缺陷，是概率的算术。</p><p>所以所有成熟的 Agent 系统都在做同一件事：<strong>用工程手段把不确定性关进笼子</strong>。显式状态机、工具白名单、人工审批点、成本上限、终止条件——这些听起来不&quot;智能&quot;，但它们是能上生产的原因。</p><h2 id="基础概念" tabindex="-1">基础概念 <a class="header-anchor" href="#基础概念" aria-label="Permalink to &quot;基础概念&quot;">​</a></h2><ul><li><strong>Agent 的四要素</strong> <span class="prio prio-must">必须</span> — LLM（决策）+ Tools（行动）+ Loop（迭代）+ Memory（状态）。缺一个就不是 Agent，只是带工具调用的问答。</li><li><strong>自主 Agent vs 工作流</strong> <span class="prio prio-must">必须</span> — Anthropic 的判断：能用工作流就别用自主 Agent。工作流可预测、可测、便宜。</li><li><strong>单步可靠性的连乘衰减</strong> <span class="prio prio-must">必须</span> — 单步 95%，十步之后约 60%。所以&quot;减少步数&quot;比&quot;提升单步&quot;收益更大。</li><li><strong>什么时候该用 Agent</strong> <span class="prio prio-must">必须</span> — 任务步数不定、路径不可预枚举、且容错空间大。三者缺一就别用。</li><li><strong>成本与延迟的现实约束</strong> <span class="prio prio-must">必须</span> — 一个 Agent 任务常常是普通问答的 10~50 倍成本，产品设计必须考虑。</li><li><strong>Agent 的价值来源</strong> <span class="prio prio-imp">重要</span> — 不是&quot;更聪明&quot;，是&quot;能执行&quot;。判断标准是它能不能改变外部世界的状态。</li></ul><h2 id="工具与协议" tabindex="-1">工具与协议 <a class="header-anchor" href="#工具与协议" aria-label="Permalink to &quot;工具与协议&quot;">​</a></h2><ul><li><strong>Function Calling 协议</strong> <span class="prio prio-must">必须</span> — 模型输出结构化调用请求，你执行后回填结果。理解完整的消息流，包括 assistant 的 tool_calls 与 tool 角色的返回。</li><li><strong>Tool Schema 设计</strong> <span class="prio prio-must">必须</span> — 参数少、类型明确、必填项少。参数越多模型填错概率越高。</li><li><strong>工具描述即 Prompt</strong> <span class="prio prio-must">必须</span> — description 写得好不好直接决定调用准确率。要写&quot;什么时候用&quot;和&quot;什么时候不用&quot;。</li><li><strong>工具粒度</strong> <span class="prio prio-must">必须</span> — 太粗（一个万能工具）模型不会用，太细（几十个工具）模型选错。按任务域分组。</li><li><strong>工具返回值设计</strong> <span class="prio prio-must">必须</span> — 返回结构化、截断过长内容、带明确的成功/失败标记。别把 10KB HTML 直接塞回去。</li><li><strong>错误返回与自愈</strong> <span class="prio prio-must">必须</span> — 错误信息要能指导模型下一步（&quot;参数 X 应为日期格式&quot;），而不是抛异常字符串。</li><li><strong>并行工具调用</strong> <span class="prio prio-imp">重要</span> — 无依赖的调用并行执行，显著降延迟。</li><li><strong>MCP（Model Context Protocol）</strong> <span class="prio prio-must">必须</span> — Anthropic 提出、已被主流厂商采纳的工具接入标准。相当于 AI 应用的 USB 接口，必学。</li><li><strong>MCP 架构</strong> <span class="prio prio-must">必须</span> — Host / Client / Server 三角色，stdio 与 HTTP+SSE 两种传输。</li><li><strong>MCP 生态与自建 Server</strong> <span class="prio prio-imp">重要</span> — 官方 server 集合、社区 server、以及把自己的内部系统包成 MCP Server。这是最容易出彩的实践方向。</li><li><strong>A2A 协议</strong> <span class="prio prio-opt">选学</span> — Agent 间通信协议，多 Agent 协作的标准尝试，了解动向即可。</li></ul><h2 id="规划范式" tabindex="-1">规划范式 <a class="header-anchor" href="#规划范式" aria-label="Permalink to &quot;规划范式&quot;">​</a></h2><ul><li><strong>ReAct 循环</strong> <span class="prio prio-must">必须</span> — Thought → Action → Observation。所有 Agent 的祖宗，先把它手写一遍。</li><li><strong>Plan-and-Execute</strong> <span class="prio prio-must">必须</span> — 先出完整计划再执行。适合步骤明确的复杂任务，省 token。</li><li><strong>Tree of Thoughts</strong> <span class="prio prio-opt">选学</span> — 多路径探索 + 剪枝。成本高，适合难题。</li><li><strong>Reflexion 自我反思</strong> <span class="prio prio-imp">重要</span> — 失败后分析原因再重试。要有明确的失败信号才有用。</li><li><strong>Router 路由</strong> <span class="prio prio-must">必须</span> — 先用小模型分类任务，再分发给不同流程。降本利器。</li><li><strong>状态机式 Agent</strong> <span class="prio prio-must">必须</span> — 用显式状态图约束流程，而不是让模型自由发挥。生产环境更常用这个。</li><li><strong>任务分解的粒度</strong> <span class="prio prio-imp">重要</span> — 拆得太细，步数多误差累积；拆得太粗，单步难度高。按&quot;单步可验证&quot;来拆。</li></ul><h2 id="记忆" tabindex="-1">记忆 <a class="header-anchor" href="#记忆" aria-label="Permalink to &quot;记忆&quot;">​</a></h2><ul><li><strong>记忆分层</strong> <span class="prio prio-imp">重要</span> — 工作记忆（当前上下文）/ 情景记忆（历史事件）/ 语义记忆（事实知识）/ 程序记忆（技能）。</li><li><strong>短期记忆与上下文管理</strong> <span class="prio prio-must">必须</span> — 滑动窗口、摘要、关键信息抽取。长对话必然要处理。</li><li><strong>长期记忆实现</strong> <span class="prio prio-imp">重要</span> — 向量库存事实 + 定期摘要。写入时机比检索算法更关键。</li><li><strong>记忆写入策略</strong> <span class="prio prio-imp">重要</span> — 不是所有对话都值得记。要有&quot;重要性打分&quot;再决定写不写。</li><li><strong>记忆冲突与遗忘</strong> <span class="prio prio-opt">选学</span> — 新旧信息矛盾时如何处理（覆盖/时间戳/并存）。这是长期记忆的真实难点。</li><li><strong>记忆检索时机</strong> <span class="prio prio-imp">重要</span> — 每次请求都检索全部记忆会污染上下文。要按相关性筛选。</li></ul><h2 id="workflow-编排模式-12-种" tabindex="-1">Workflow 编排模式（12 种） <a class="header-anchor" href="#workflow-编排模式-12-种" aria-label="Permalink to &quot;Workflow 编排模式（12 种）&quot;">​</a></h2><p>Anthropic 在《Building Effective Agents》里把这些叫 &quot;workflows&quot;——路径预先定义，模型只负责单步。<strong>生产环境 80% 的需求靠这 12 种模式就够，不需要自主 Agent。</strong></p><ul><li><strong>Sequential（顺序链）</strong> <span class="prio prio-must">必须</span> — A 的输出喂给 B。最基础，也最可靠。典型：抽取 → 校验 → 格式化。</li><li><strong>Parallel（并行）</strong> <span class="prio prio-must">必须</span> — 多个独立子任务同时跑，最后合并。<strong>降延迟最直接的手段</strong>。</li><li><strong>Conditional（条件分支）</strong> <span class="prio prio-must">必须</span> — 按分类结果走不同分支。分支判断最好用代码或小模型，别用大模型&quot;自由决定&quot;。</li><li><strong>Fan-out / Fan-in（扇出扇入）</strong> <span class="prio prio-imp">重要</span> — 一个任务拆成 N 份并行处理再聚合。文档批量处理的标准形态。</li><li><strong>Map-Reduce</strong> <span class="prio prio-imp">重要</span> — Fan-out 的特例：每份独立处理（map），再汇总（reduce）。<strong>长文档摘要必用</strong>，且要分层 reduce。</li><li><strong>Router（路由）</strong> <span class="prio prio-must">必须</span> — 入口先分类，再分发。降本利器：简单问题走小模型。</li><li><strong>Supervisor（主管）</strong> <span class="prio prio-imp">重要</span> — 一个调度者决定&quot;下一步谁来做&quot;，工人不互相说话。<strong>比自由协作可控得多</strong>。</li><li><strong>Planner-Executor（规划-执行）</strong> <span class="prio prio-must">必须</span> — 规划者出计划，执行者逐步做。计划可审阅、可缓存、可复用。</li><li><strong>Evaluator-Optimizer（评估-优化）</strong> <span class="prio prio-imp">重要</span> — 生成 → 评估 → 打回重写，循环到达标。<strong>必须设最大轮数</strong>，否则死循环。</li><li><strong>HITL（人工介入）</strong> <span class="prio prio-must">必须</span> — 关键节点暂停等审批。审批点要设计成&quot;状态挂起&quot;而非&quot;线程阻塞&quot;。</li><li><strong>Event-driven（事件驱动）</strong> <span class="prio prio-imp">重要</span> — 由外部事件触发（新邮件、新工单、定时器）。<strong>这是 Agent 从&quot;聊天框&quot;走向&quot;后台员工&quot;的关键</strong>。</li><li><strong>DAG（有向无环图）</strong> <span class="prio prio-must">必须</span> — 把上面这些组合成图：节点是步骤，边是依赖。LangGraph / Airflow / Temporal 都是这个思路。<strong>能画出 DAG 就说明你想清楚了。</strong></li></ul><p><strong>怎么选</strong>：先问&quot;路径能不能预先枚举&quot;。能 → 用 workflow（上面 12 种随便组合）；不能 → 才考虑自主 Agent。<strong>面试答&quot;我们先用 DAG 编排，只有真正开放的任务才交给自主循环&quot;，比答&quot;我们用了多 Agent 协作&quot;分数高得多。</strong></p><h2 id="自主性等级与权限模式" tabindex="-1">自主性等级与权限模式 <a class="header-anchor" href="#自主性等级与权限模式" aria-label="Permalink to &quot;自主性等级与权限模式&quot;">​</a></h2><p>同一个 Agent，权限模式不同，风险差一个数量级。产品上必须显式选择，不能默认全开。</p><ul><li><strong>Read-only（只读）</strong> <span class="prio prio-must">必须</span> — 只能查，不能改。最安全，适合&quot;分析助手&quot;。</li><li><strong>Suggest（建议）</strong> <span class="prio prio-must">必须</span> — 产出方案但不执行，由人点&quot;确认&quot;。<strong>To B 场景的默认档</strong>。</li><li><strong>Approval Required（需审批）</strong> <span class="prio prio-must">必须</span> — 高风险动作（付款、删除、发外部邮件）单独审批，低风险动作自动执行。<strong>分级授权比一刀切好用</strong>。</li><li><strong>Execute（自动执行）</strong> <span class="prio prio-imp">重要</span> — 全自动。只适合可逆、低价值、有兜底的场景（如整理标签、生成草稿）。</li><li><strong>权限继承原则</strong> <span class="prio prio-must">必须</span> — Agent 的权限上限 = 当前用户的权限，<strong>绝不能是服务账号的权限</strong>。这是越权事故的头号成因。</li><li><strong>动作分级表</strong> <span class="prio prio-imp">重要</span> — 把工具按&quot;可逆性 × 影响范围&quot;分四档，每档对应一个权限模式。<strong>先列表再写代码</strong>，这张表就是产品需求文档。</li></ul><h2 id="工具类型目录" tabindex="-1">工具类型目录 <a class="header-anchor" href="#工具类型目录" aria-label="Permalink to &quot;工具类型目录&quot;">​</a></h2><p>面试问&quot;你给 Agent 配了哪些工具&quot;，答不出分类说明没系统想过。</p><ul><li><strong>查询类（Read）</strong> <span class="prio prio-must">必须</span> — 搜索、读文件、查库、调 API。无副作用，可随意重试。</li><li><strong>写入类（Write）</strong> <span class="prio prio-must">必须</span> — 建记录、改状态、发消息。<strong>必须幂等 + 审计</strong>。</li><li><strong>计算类（Compute）</strong> <span class="prio prio-must">必须</span> — 代码执行、数学计算、格式转换。<strong>别让模型心算</strong>，交给工具。</li><li><strong>检索类（Retrieve）</strong> <span class="prio prio-must">必须</span> — RAG 检索、向量查询。和查询类的区别是&quot;模糊 vs 精确&quot;。</li><li><strong>通信类（Communicate）</strong> <span class="prio prio-imp">重要</span> — 发邮件、发 IM、创建工单。<strong>外部可见，风险最高</strong>。</li><li><strong>编排类（Orchestrate）</strong> <span class="prio prio-imp">重要</span> — 调用子 Agent、启动子任务。要有深度限制，防递归爆炸。</li><li><strong>人机类（Human）</strong> <span class="prio prio-imp">重要</span> — 请求澄清、请求审批、转人工。<strong>这个工具最容易被忘，但没有它 Agent 只能瞎猜</strong>。</li><li><strong>工具数量上限</strong> <span class="prio prio-must">必须</span> — 一次给模型超过 20 个工具，选择准确率明显下降。<strong>按场景动态加载工具子集</strong>，这是 MCP + Skill 存在的意义。</li></ul><h2 id="多-agent-体系" tabindex="-1">多 Agent 体系 <a class="header-anchor" href="#多-agent-体系" aria-label="Permalink to &quot;多 Agent 体系&quot;">​</a></h2><ul><li><strong>协作模式</strong> <span class="prio prio-imp">重要</span> — 顺序 / 并行 / 辩论 / 层级（主管-工人）。</li><li><strong>Role（角色）</strong> <span class="prio prio-imp">重要</span> — 每个 Agent 一个明确职责。<strong>角色是&quot;职责边界&quot;，不是&quot;人格设定&quot;</strong>。</li><li><strong>Specialist（专家）</strong> <span class="prio prio-imp">重要</span> — 窄领域深能力。比如&quot;只做 SQL 生成&quot;、&quot;只做合同条款抽取&quot;。</li><li><strong>Worker（工人）</strong> <span class="prio prio-imp">重要</span> — 执行具体动作，不做决策。可并行复制多个。</li><li><strong>Handoff（交接）</strong> <span class="prio prio-must">必须</span> — A 把控制权交给 B，附带结构化上下文。<strong>OpenAI Agents SDK 的核心概念</strong>。交接要传递&quot;已确认的事实&quot;，不是完整对话。</li><li><strong>Shared State（共享状态）</strong> <span class="prio prio-must">必须</span> — 多个 Agent 读写同一份状态。<strong>必须有并发控制</strong>，否则互相覆盖。</li><li><strong>Blackboard（黑板）</strong> <span class="prio prio-imp">重要</span> — 共享状态的一种：所有 Agent 往同一块区域写结论，谁需要谁读。适合松散协作。</li><li><strong>Conflict Resolution（冲突消解）</strong> <span class="prio prio-imp">重要</span> — 两个 Agent 结论矛盾怎么办？投票 / 更高优先级者胜 / 升级给人 / 让第三个 Agent 裁决。</li><li><strong>Result Aggregation（结果聚合）</strong> <span class="prio prio-must">必须</span> — 多份输出合并。<strong>别让模型&quot;自由合并&quot;</strong>，用结构化字段逐项对比。</li><li><strong>A2A 协议</strong> <span class="prio prio-opt">选学</span> — Agent 间通信标准（Agent Card 发现 + 任务协作）。了解动向即可，生产用得还少。</li><li><strong>上下文隔离与消息传递</strong> <span class="prio prio-must">必须</span> — 只传结构化结论，不传完整对话，否则污染爆炸。</li><li><strong>多 Agent 的真实收益</strong> <span class="prio prio-must">必须</span> — 多数场景下多 Agent 不如一个好 Agent + 好工具。<strong>别为了架构而架构</strong>。真实收益主要来自&quot;上下文隔离&quot;（每个 Agent 上下文更干净）和&quot;并行&quot;。</li></ul><h2 id="agent-框架选型" tabindex="-1">Agent 框架选型 <a class="header-anchor" href="#agent-框架选型" aria-label="Permalink to &quot;Agent 框架选型&quot;">​</a></h2><ul><li><strong>LangGraph</strong> <span class="prio prio-must">必须</span> — 图 + 显式状态 + checkpoint。<strong>生产首选</strong>，可控性最好，Python/JS 都有。</li><li><strong>OpenAI Agents SDK</strong> <span class="prio prio-must">必须</span> — 轻量，核心是 Agent + Handoff + Guardrail + Session。<strong>概念最少，最容易读懂</strong>。</li><li><strong>Vercel AI SDK</strong> <span class="prio prio-must">必须</span> — TS 生态首选。<code>streamText</code> / <code>generateObject</code> / 工具调用 / UI 流式一体化。<strong>前端转过来最顺手</strong>。</li><li><strong>LangChain</strong> <span class="prio prio-imp">重要</span> — 抽象层多、版本变动大。<strong>建议读它的源码理解概念，但新项目别从它起步</strong>。</li><li><strong>Mastra</strong> <span class="prio prio-imp">重要</span> — TS 原生的 Agent 框架，工作流 + 记忆 + 评测都有。TS 团队可以看看。</li><li><strong>PydanticAI</strong> <span class="prio prio-imp">重要</span> — 类型安全的 Python Agent 框架，和 FastAPI/Pydantic 生态一致。</li><li><strong>AutoGen / CrewAI</strong> <span class="prio prio-opt">选学</span> — 多 Agent 协作框架。<strong>demo 很惊艳，生产要谨慎</strong>：可控性和可观测性偏弱。</li><li><strong>Semantic Kernel</strong> <span class="prio prio-opt">选学</span> — 微软系，.NET/Java 生态友好。</li><li><strong>选型三条标准</strong> <span class="prio prio-must">必须</span> — ① 有没有显式状态和 checkpoint（能不能恢复）② 能不能接入自己的可观测（能不能排障）③ 锁不锁定模型厂商（能不能换）。<strong>三条里缺 checkpoint 直接排除。</strong></li></ul><h2 id="状态管理" tabindex="-1">状态管理 <a class="header-anchor" href="#状态管理" aria-label="Permalink to &quot;状态管理&quot;">​</a></h2><p>任务级状态（不是用户记忆，那部分见 <a href="/ai-eng-roadmap/guide/22-memory">22 · 记忆系统</a>）。</p><ul><li><strong>状态序列化</strong> <span class="prio prio-must">必须</span> — 状态必须能落成 JSON。<strong>只存在进程内存的状态 = 重启就丢</strong>。</li><li><strong>任务锁</strong> <span class="prio prio-must">必须</span> — 同一任务不能被两个 worker 同时推进。<code>SELECT ... FOR UPDATE</code> 或 Redis 分布式锁。</li><li><strong>并发控制</strong> <span class="prio prio-imp">重要</span> — 多任务抢同一资源（同一文档、同一订单）时的顺序问题。</li><li><strong>Saga / 补偿链</strong> <span class="prio prio-must">必须</span> — 多步副作用操作，每步都要有对应的 undo。第 3 步失败要撤销第 1、2 步。</li><li><strong>状态版本兼容</strong> <span class="prio prio-imp">重要</span> — 给状态加 <code>schema_version</code> + 迁移函数。<strong>跑几小时的长任务一定会跨版本</strong>。</li><li><strong>子任务隔离</strong> <span class="prio prio-imp">重要</span> — 子 Agent 崩溃不能带崩主流程。要有独立的超时和错误边界。</li></ul><h2 id="可靠性工程" tabindex="-1">可靠性工程 <a class="header-anchor" href="#可靠性工程" aria-label="Permalink to &quot;可靠性工程&quot;">​</a></h2><ul><li><strong>循环终止条件</strong> <span class="prio prio-must">必须</span> — 最大步数、最大成本、无进展检测。三个都要有，缺一个就可能烧钱。</li><li><strong>超时与重试</strong> <span class="prio prio-must">必须</span> — 工具调用必须有超时，重试要退避且限次。</li><li><strong>幂等与副作用</strong> <span class="prio prio-must">必须</span> — 写操作要幂等键，避免重试导致重复下单/重复发信。</li><li><strong>人机协同 HITL</strong> <span class="prio prio-must">必须</span> — 高风险动作前插入审批点。这是 Agent 落地的必要条件，不是可选项。</li><li><strong>中断与恢复</strong> <span class="prio prio-imp">重要</span> — 任务可暂停、可恢复、可回滚。长任务必须支持。</li><li><strong>成本上限控制</strong> <span class="prio prio-must">必须</span> — 按任务设 token 预算，超了降级或终止。</li><li><strong>可观测性</strong> <span class="prio prio-must">必须</span> — 每一步的输入输出都要能回放，否则出问题无法定位。</li><li><strong>Agent 评估的困难</strong> <span class="prio prio-imp">重要</span> — 路径不唯一，不能只比最终答案。需要评&quot;过程合理性&quot;与&quot;效率&quot;。</li><li><strong>降级路径</strong> <span class="prio prio-imp">重要</span> — Agent 卡住时要能退化成&quot;给用户一个半成品 + 人工接管&quot;。</li></ul><h2 id="执行环境" tabindex="-1">执行环境 <a class="header-anchor" href="#执行环境" aria-label="Permalink to &quot;执行环境&quot;">​</a></h2><ul><li><strong>代码解释器 / 沙箱</strong> <span class="prio prio-must">必须</span> — 执行模型生成的代码必须隔离：无网络、限资源、限时。</li><li><strong>Computer Use / Browser Use</strong> <span class="prio prio-imp">重要</span> — 让模型操作浏览器或桌面。能力上限高但稳定性差，适合有兜底的场景。</li><li><strong>文件系统与工作区</strong> <span class="prio prio-imp">重要</span> — 给 Agent 一个可读写的临时工作区，比全靠上下文传递更可靠。</li><li><strong>权限边界</strong> <span class="prio prio-must">必须</span> — Agent 代表用户操作时，权限必须是&quot;用户的权限&quot;而非&quot;系统的权限&quot;。</li></ul><h2 id="mcp-server-开发-会用-会做" tabindex="-1">MCP Server 开发（会用 ≠ 会做） <a class="header-anchor" href="#mcp-server-开发-会用-会做" aria-label="Permalink to &quot;MCP Server 开发（会用 ≠ 会做）&quot;">​</a></h2><p>前面讲了 MCP 是什么，但<strong>面试问的是&quot;你写过 MCP Server 吗&quot;</strong>。这一节补齐。</p><ul><li><strong>最小 Server 结构</strong> <span class="prio prio-must">必须</span> — 注册 server 信息 → 声明 capabilities → 实现 tool/resource handler → 连接 transport。三十行能跑起来一个。</li><li><strong>Tool 定义三要素</strong> <span class="prio prio-must">必须</span> — name、description、inputSchema（JSON Schema）。<strong>description 是给模型看的，要写清&quot;什么时候用&quot;。</strong></li><li><strong>返回值结构</strong> <span class="prio prio-must">必须</span> — <code>content</code> 数组，每项有 type（text/image/resource）。<strong><code>isError</code> 标记很关键</strong>，模型靠它判断要不要重试。</li><li><strong>Resource 与 Tool 的区别</strong> <span class="prio prio-imp">重要</span> — Resource 是被动的、可读取的数据（URI 寻址）；Tool 是主动的、有副作用的操作。别把查询做成 Tool，那是 Resource。</li><li><strong>Prompts 能力</strong> <span class="prio prio-opt">选学</span> — 服务端预置的提示模板，供客户端调用。</li><li><strong>stdio 传输</strong> <span class="prio prio-must">必须</span> — 本地进程，通过标准输入输出通信。适合本地工具，不能用于远程。</li><li><strong>Streamable HTTP 传输</strong> <span class="prio prio-must">必须</span> — 远程部署用，支持 SSE 流式响应和会话管理。</li><li><strong>能力协商</strong> <span class="prio prio-imp">重要</span> — 初始化时双方声明支持的能力，客户端只能调服务端声明过的。</li><li><strong>进度通知与取消</strong> <span class="prio prio-imp">重要</span> — 长任务要发 progress 通知；客户端取消要能中止服务端执行。</li><li><strong>认证</strong> <span class="prio prio-must">必须</span> — 远程 Server 必须做认证（OAuth 或 token），并且<strong>把调用者身份透传到业务逻辑</strong>，否则权限无从谈起。</li><li><strong>MCP Inspector 调试</strong> <span class="prio prio-must">必须</span> — 官方调试工具，能看到原始 JSON-RPC 消息。写 Server 必用。</li><li><strong>信任边界</strong> <span class="prio prio-must">必须</span> — 第三方 Server 等于在你机器上跑任意代码。生产环境要白名单 + 审计。</li><li><strong>测试</strong> <span class="prio prio-imp">重要</span> — 直接测 handler 函数（单元），再用 Inspector 测协议层（集成）。</li></ul><h2 id="workflow-与持久化执行" tabindex="-1">Workflow 与持久化执行 <a class="header-anchor" href="#workflow-与持久化执行" aria-label="Permalink to &quot;Workflow 与持久化执行&quot;">​</a></h2><p>Agent 最容易翻车的地方不是&quot;不会做&quot;，是&quot;做到一半挂了&quot;。这一节解决它。</p><ul><li><strong>状态机 vs 自由循环</strong> <span class="prio prio-must">必须</span> — 生产环境优先状态机：每个状态允许的动作是枚举的，非法转移直接报错。自由循环只适合探索阶段。</li><li><strong>Checkpoint 的时机</strong> <span class="prio prio-must">必须</span> — 每步执行完就存，不要等任务结束。存的内容是&quot;完整可序列化的运行时状态&quot;，不是日志。</li><li><strong>持久化执行（Durable Execution）</strong> <span class="prio prio-must">必须</span> — 服务器重启后从最后一个 checkpoint 继续，而不是从头跑。Temporal / Inngest / LangGraph 都在解决这个。</li><li><strong>中断与恢复</strong> <span class="prio prio-must">必须</span> — 暂停要能保存现场，恢复要能接着做。人工审批本质就是一次长时间中断。</li><li><strong>补偿（Compensation）</strong> <span class="prio prio-imp">重要</span> — 已经执行了副作用但后续失败，要能撤销。比如发了邮件但后面步骤失败，要能发更正。</li><li><strong>幂等重放</strong> <span class="prio prio-must">必须</span> — 从 checkpoint 恢复时，那一步可能已经执行过。必须靠幂等键保证不重复。</li><li><strong>状态版本兼容</strong> <span class="prio prio-imp">重要</span> — 代码升级后旧 checkpoint 可能反序列化失败。要版本号 + 迁移。</li><li><strong>超时分层</strong> <span class="prio prio-must">必须</span> — 步骤超时、任务总超时、审批超时（超时自动拒绝还是通过？要明确）。</li></ul><h2 id="agent-skills" tabindex="-1">Agent Skills <a class="header-anchor" href="#agent-skills" aria-label="Permalink to &quot;Agent Skills&quot;">​</a></h2><ul><li><strong>Skill 是什么</strong> <span class="prio prio-must">必须</span> — 把&quot;做某类任务的方法&quot;封装成可复用的文档 + 脚本 + 资源，模型按需加载。</li><li><strong><code>SKILL.md</code> 结构</strong> <span class="prio prio-must">必须</span> — 元信息（名称、触发条件）+ 操作步骤 + 注意事项 + 依赖资源。</li><li><strong>渐进披露（Progressive Disclosure）</strong> <span class="prio prio-must">必须</span> — 先给模型看摘要，需要时再加载全文。<strong>这是 Skill 相对&quot;塞进 system prompt&quot;的核心优势</strong>——不占常驻上下文。</li><li><strong>触发条件怎么写</strong> <span class="prio prio-must">必须</span> — 要写&quot;什么情况下用&quot;，不是&quot;这是什么&quot;。写不好就不会被触发。</li><li><strong>与 Function Calling / MCP 的区别</strong> <span class="prio prio-must">必须</span> — Function Calling 是&quot;调一个函数&quot;，MCP 是&quot;接一个工具服务&quot;，Skill 是&quot;教一套方法&quot;。三者不互斥，常常一起用。</li><li><strong>脚本与资源</strong> <span class="prio prio-imp">重要</span> — Skill 可以带可执行脚本，但要声明依赖和权限。</li><li><strong>版本与测试</strong> <span class="prio prio-imp">重要</span> — Skill 改了要回归测试，否则会静默失效。</li></ul><h2 id="行业黑话对照-听到别慌" tabindex="-1">行业黑话对照（听到别慌） <a class="header-anchor" href="#行业黑话对照-听到别慌" aria-label="Permalink to &quot;行业黑话对照（听到别慌）&quot;">​</a></h2><p>2025 年之后冒出一批新词，<strong>内容你都在这章学过，但词不认识会显得脱节</strong>。面试官很可能直接用这些词提问。</p><ul><li><strong>Harness Engineering（脚手架工程）</strong> <span class="prio prio-must">必须</span> — 给 Agent 搭的那套外部结构：工具集、状态管理、checkpoint、审批点、失败重试、验证回路。<strong>就是本章&quot;用工程手段把不确定性关进笼子&quot;那件事，行业给它单独立了个名</strong>。核心洞察是：<strong>瓶颈不在模型，在脚手架</strong>。</li><li><strong>Loop Engineering（循环工程）</strong> <span class="prio prio-must">必须</span> — 设计 Agent 的迭代循环：每步看什么、能调什么、什么算成功、什么时候停。<strong>等于 ReAct 循环 + 终止条件 + 无进展检测</strong>。指标是&quot;收敛速度&quot;和&quot;不收敛时的止损&quot;。</li><li><strong>Agentic Workflow</strong> <span class="prio prio-imp">重要</span> — 工作流里嵌 Agent 节点，而不是全自主。<strong>这是目前生产环境的主流形态</strong>，对应上面 12 种编排模式的组合。</li><li><strong>Context Engineering</strong> <span class="prio prio-imp">重要</span> — 见 <a href="/ai-eng-roadmap/guide/02-prompt-context">02 · Prompt 与上下文</a>。行业共识：它比 prompt 措辞更重要。</li><li><strong>Spec-driven Development</strong> <span class="prio prio-opt">选学</span> — 先写可执行的规格再让 AI 实现。见 <a href="/ai-eng-roadmap/guide/24-ai-assisted-dev">24 · AI 辅助研发</a>。</li><li><strong>DeepAgent / 各类&quot;深度&quot;框架</strong> <span class="prio prio-opt">选学</span> — 厂商起的框架名，本质是&quot;规划 + 子 Agent + 文件系统&quot;。<strong>属 LangGraph 同类，理解模式即可，不必专门学品牌</strong>。</li><li><strong>应对陌生术语的方法</strong> <span class="prio prio-must">必须</span> — 先问&quot;它对应我已知的哪个模式&quot;。<strong>九成新词是旧概念换了包装</strong>，剩下的才是真新东西。这个能力比背术语值钱。</li></ul><h2 id="本章对应的面试题" tabindex="-1">本章对应的面试题 <a class="header-anchor" href="#本章对应的面试题" aria-label="Permalink to &quot;本章对应的面试题&quot;">​</a></h2><p>共 20 题，见 <a href="/ai-eng-roadmap/guide/15-interview#e-agent-20-题">15 · 面试题库 · E 组</a>。</p><p>最关键的是第一题：<strong>什么时候该用 Agent，什么时候用工作流</strong>。答&quot;Agent 更先进&quot;会被直接扣分——正确的答案是&quot;工作流优先，只有当步骤无法预先枚举时才用 Agent&quot;。</p><p>配套动手部分见 <a href="/ai-eng-roadmap/guide/16-projects">16 · 项目实战 · 项目 2</a>。</p>',49)])])}const q=o(i,[["render",a]]);export{m as __pageData,q as default};
